            else:
                template_contents = ''
            templates.append({
                'file': template_file,
                'exists': template_file.exists(),
                'contents': template_contents,
                'order': index,
            })
    return super().get_context_data(**{
        **kwargs,
        'name': template,
        'templates': templates,
    })

