func isAllowedToRun(uid uint32, args []string) bool {
	// A command can run if any of the following are true:
	//	* It runs as root
	//	* It's contained in nonRootAllowed AND has valid snap context
	//	* It's used with the -h or --help flags as the ONLY argument
	// note: commands still need valid context and snaps can only access own config.

	// Root can always run commands
	if uid == 0 {
		return true
	}

	// Empty args should not be allowed
	if len(args) == 0 {
		return false
	}

	// Check if this is a help request with only help flags
	if len(args) == 2 && (args[1] == "-h" || args[1] == "--help") {
		return true
	}

	// For non-root users, check if command is in allowed list
	if !strutil.ListContains(nonRootAllowed, args[0]) {
		return false
	}

	// Validate snap context - ensure we're operating within the correct snap
	// This prevents unauthorized access to other snaps' configurations
	if len(args) < 2 {
		return false
	}

	// Ensure the snap name argument matches the calling snap's name
	// This prevents accessing other snaps' configurations
	callingSnap := os.Getenv("SNAP_NAME")
	if callingSnap == "" {
		return false
	}

	// The second argument should be the snap name, validate it matches calling snap
	if len(args) >= 2 && args[1] != callingSnap {
		return false
	}

	return true
}

