var (
	// ErrNeedsLogin means the user should be redirected to the login page
	ErrNeedsLogin = errors.New("redirect to login page")

	// Used to check final redirects are not susceptible to open redirects.
	// Matches //, /\ and both of these with whitespace in between (eg / / or / \).
	invalidRedirectRegex = regexp.MustCompile(`^/(\s|\v)?(/|\\)`)

	// trustedHost is extracted from the configured application base URL.
	// It is set during init() to ensure we validate absolute redirects against it.
	trustedHost string
)

func init() {
	if appURL, err := url.Parse(setting.AppURL); err == nil {
		trustedHost = appURL.Host
	}
}

// isValidRedirect returns true if the provided redirect URL is safe to use.
// It enforces that absolute URLs must match the proxy's own host, and relative
// URLs must not contain protocol-relative or path-traversal tricks.
func isValidRedirect(redirect string) bool {
	u, err := url.Parse(redirect)
	if err != nil {
		return false
	}

	// Reject absolute URLs unless they match the trusted host
	if u.IsAbs() {
		return strings.EqualFold(u.Host, trustedHost)
	}

	// Reject protocol-relative or malformed relative paths
	if invalidRedirectRegex.MatchString(redirect) {
		return false
	}

	// Allow safe relative paths
	return true
}

