func isRepositoryGitPath(path string) bool {
	// Normalize the path to resolve any directory traversal sequences
	normalizedPath := filepath.Clean(path)

	// Check if the normalized path ends with .git or contains .git as a directory
	base := filepath.Base(normalizedPath)
	if base == ".git" || strings.HasPrefix(base, ".git.") {
		return true
	}

	// Split the path and check each component
	parts := strings.Split(normalizedPath, string(filepath.Separator))
	for _, part := range parts {
		if part == ".git" || strings.HasPrefix(part, ".git.") {
			return true
		}
	}

	return false
}

