func isLoopbackURI(requested *url.URL, registeredURI string) bool {
	registered, err := url.Parse(registeredURI)
	if err != nil {
		return false
	}

	// Ensure both schemes are HTTP
	if registered.Scheme != "http" || requested.Scheme != "http" {
		return false
	}

	// Ensure both hosts are loopback addresses
	if !isLoopbackAddress(registered.Host) || !isLoopbackAddress(requested.Host) {
		return false
	}

	// Ensure the hosts match exactly (prevent host override)
	if registered.Host != requested.Host {
		return false
	}

	// Ensure the paths match exactly
	if registered.Path != requested.Path {
		return false
	}

	// Ensure no additional query parameters are injected
	// Only allow query parameters that are present in the registered URI
	registeredQuery := registered.Query()
	requestedQuery := requested.Query()

	// Check if all requested query parameters are in the registered query
	for key := range requestedQuery {
		if !registeredQuery.Has(key) {
			return false
		}
		// Ensure the values match for each parameter
		if requestedQuery.Get(key) != registeredQuery.Get(key) {
			return false
		}
	}

	return true
}

