// validatePath ensures that the given path does not escape the destination directory
// through symlinks. It checks each directory component to ensure no symlinks point
// outside the destination directory.
func validatePath(dst, path string) error {
	// Ensure both paths are clean and absolute.
	dst = filepath.Clean(dst)
	path = filepath.Clean(path)

	// Check if the path is within the destination directory.
	rel, err := filepath.Rel(dst, path)
	if err != nil || strings.HasPrefix(rel, "..") {
		return fmt.Errorf("path escapes destination directory")
	}

	// Walk up the path and check each component for symlinks.
	current := path
	for {
		// Check if the current path exists and is a symlink.
		info, err := os.Lstat(current)
		if err != nil {
			// If the path doesn't exist, that's okay - we're creating it.
			if os.IsNotExist(err) {
				// Check parent directories
				parent := filepath.Dir(current)
				if parent == current || parent == dst {
					break
				}
				current = parent
				continue
			}
			return err
		}

		// If this is a symlink, resolve it and check if it escapes.
		if info.Mode()&os.ModeSymlink != 0 {
			target, err := os.Readlink(current)
			if err != nil {
				return err
			}

			// Resolve relative symlinks.
			if !filepath.IsAbs(target) {
				target = filepath.Join(filepath.Dir(current), target)
			}

			// Ensure the resolved symlink target is within the destination directory.
			absTarget, err := filepath.Abs(target)
			if err != nil {
				return err
			}
			absTarget = filepath.Clean(absTarget)

			relTarget, err := filepath.Rel(dst, absTarget)
			if err != nil || strings.HasPrefix(relTarget, "..") {
				return fmt.Errorf("symlink points outside destination directory")
			}
		}

		// Move up to the parent directory.
		parent := filepath.Dir(current)
		if parent == current || parent == dst {
			break
		}
		current = parent
	}

	return nil
}

