	// We need to check if any intermediate path component is a symlink
	// that would cause us to escape the destination directory.
	current := dst
	components := strings.Split(rel, string(filepath.Separator))

	for _, component := range components {
		if component == "" {
			continue
		}

		current = filepath.Join(current, component)
		current = filepath.Clean(current)

		// Check if this path exists and resolve any symlinks.
		info, err := os.Lstat(current)
		if err != nil {
			if os.IsNotExist(err) {
				// Path doesn't exist yet, that's okay for new files
				continue
			}
			return err
		}

		// If this is a symlink, resolve it and check the target.
		if info.Mode()&os.ModeSymlink != 0 {
			target, err := os.Readlink(current)
			if err != nil {
				return err
			}

			// Resolve relative symlinks.
			if !filepath.IsAbs(target) {
				target = filepath.Join(filepath.Dir(current), target)
			}

			absTarget, err := filepath.Abs(target)
			if err != nil {
				return err
			}
			absTarget = filepath.Clean(absTarget)

			// Ensure the symlink target is within the destination directory.
			relTarget, err := filepath.Rel(dst, absTarget)
			if err != nil || strings.HasPrefix(relTarget, "..") {
				return fmt.Errorf("symlink points outside destination directory")
			}

			// Update current to the resolved target for further checks.
			current = absTarget
		}
	}

	return nil
}

