		path = filepath.Clean(path)
		if strings.HasPrefix(path, "..") {
			return fmt.Errorf("Invalid file path %q: attempts to escape destination directory", header.Name)
		}

		// Join with destination directory.
		fullPath := filepath.Join(absDst, path)

		// Ensure the path is within the destination directory.
		relPath, err := filepath.Rel(absDst, fullPath)
		if err != nil || strings.HasPrefix(relPath, "..") {
			return fmt.Errorf("Invalid file path %q: attempts to escape destination directory", header.Name)
		}

		// Handle symlinks.
		if header.Typeflag == tar.TypeSymlink {
			// Disallow absolute targets.
			if filepath.IsAbs(header.Linkname) {
				return fmt.Errorf("Invalid symlink (%q -> %q) has absolute target",
					header.Name, header.Linkname)
			}

			// Resolve the symlink target path.
			target := filepath.Join(filepath.Dir(fullPath), header.Linkname)
			target = filepath.Clean(target)

			// Ensure the resolved target is within the destination directory.
			relTarget, err := filepath.Rel(absDst, target)
			if err != nil || strings.HasPrefix(relTarget, "..") {
				return fmt.Errorf("Invalid symlink (%q -> %q) has external target",
					header.Name, header.Linkname)
			}

			// Create parent directories for the symlink.
			dir := filepath.Dir(fullPath)
			if err := os.MkdirAll(dir, 0755); err != nil {
				return fmt.Errorf("Failed to create directory %q: %v", dir, err)
			}

			// Create the symlink.
			if err := os.Symlink(header.Linkname, fullPath); err != nil {
				return fmt.Errorf("Failed creating symlink (%q -> %q): %v",
					header.Name, header.Linkname, err)
			}

			continue
		}

		// Make the directories to the path.
		dir := filepath.Dir(fullPath)
		if err := os.MkdirAll(dir, 0755); err != nil {
