			}
			continue
		} else if header.Typeflag != tar.TypeReg && header.Typeflag != tar.TypeRegA {
			return fmt.Errorf("Failed creating %q: unsupported type %c", fullPath,
				header.Typeflag)
		}

		// Open a handle to the destination.
		fh, err := os.Create(fullPath)
		if err != nil {
			// This mimics tar's behavior wrt the tar file containing duplicate files
			// and it allowing later ones to clobber earlier ones even if the file
			// has perms that don't allow overwriting.
			if os.IsPermission(err) {
				os.Chmod(fullPath, 0600)
				fh, err = os.Create(fullPath)
			}

			if err != nil {
				return fmt.Errorf("Failed creating file %q: %v", fullPath, err)
			}
		}

		// Copy the contents.
		_, err = io.Copy(fh, untar)
		fh.Close()
		if err != nil {
			return fmt.Errorf("Failed to copy slug file %q: %v", fullPath, err)
		}

