func Unpack(r io.Reader, dst string) error {
	// Decompress as we read.
	uncompressed, err := gzip.NewReader(r)
	if err != nil {
		return fmt.Errorf("Failed to uncompress slug: %v", err)
	}

	// Untar as we read.
	untar := tar.NewReader(uncompressed)

	// Ensure the destination directory is absolute and clean.
	absDst, err := filepath.Abs(dst)
	if err != nil {
		return fmt.Errorf("Failed to get absolute path for destination: %v", err)
	}
	absDst = filepath.Clean(absDst)

	// Unpackage all the contents into the directory.
	for {
		header, err := untar.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			return fmt.Errorf("Failed to untar slug: %v", err)
		}

		// Get rid of absolute paths.
		path := header.Name
		if filepath.IsAbs(path) {
			path = path[1:]
		}

		// Clean the path to prevent directory traversal.
		path = filepath.Clean(path)
		if strings.HasPrefix(path, "..") {
			return fmt.Errorf("Cannot extract %q: attempts to escape destination directory", header.Name)
		}

		// Join with destination directory.
		fullPath := filepath.Join(absDst, path)

		// Ensure the path is within the destination directory.
		relPath, err := filepath.Rel(absDst, fullPath)
		if err != nil || strings.HasPrefix(relPath, "..") {
			return fmt.Errorf("Cannot extract %q: attempts to escape destination directory", header.Name)
		}

		// Handle symlinks.
		if header.Typeflag == tar.TypeSymlink {
			// Disallow absolute targets.
			if filepath.IsAbs(header.Linkname) {
				return fmt.Errorf("Invalid symlink (%q -> %q) has absolute target",
					header.Name, header.Linkname)
			}

			// Resolve the symlink target path.
			target := filepath.Join(filepath.Dir(fullPath), header.Linkname)
			target = filepath.Clean(target)

			// Ensure the resolved target is within the destination directory.
			relTarget, err := filepath.Rel(absDst, target)
			if err != nil || strings.HasPrefix(relTarget, "..") {
				return fmt.Errorf("Cannot extract %q through symlink: attempts to escape destination directory", header.Name)
			}

			// Create parent directories for the symlink.
			dir := filepath.Dir(fullPath)
			if err := os.MkdirAll(dir, 0755); err != nil {
				return fmt.Errorf("Failed to create directory %q: %v", dir, err)
			}

			// Create the symlink.
			if err := os.Symlink(header.Linkname, fullPath); err != nil {
				return fmt.Errorf("Failed creating symlink (%q -> %q): %v",
					header.Name, header.Linkname, err)
			}

			continue
		}

		// Make the directories to the path.
		dir := filepath.Dir(fullPath)
		if err := os.MkdirAll(dir, 0755); err != nil {
			return fmt.Errorf("Failed to create directory %q: %v", dir, err)
		}

		// Only unpack regular files from this point on.
		if header.Typeflag == tar.TypeDir {
			if err := os.MkdirAll(fullPath, header.FileInfo().Mode()); err != nil {
				return fmt.Errorf("Failed to create directory %q: %v", fullPath, err)
			}
			continue
		} else if header.Typeflag != tar.TypeReg && header.Typeflag != tar.TypeRegA {
			return fmt.Errorf("Failed creating %q: unsupported type %c", fullPath,
				header.Typeflag)
		}

		// Open a handle to the destination.
		fh, err := os.Create(fullPath)
		if err != nil {
			// This mimics tar's behavior wrt the tar file containing duplicate files
			// and it allowing later ones to clobber earlier ones even if the file
			// has perms that don't allow overwriting.
			if os.IsPermission(err) {
				os.Chmod(fullPath, 0600)
				fh, err = os.Create(fullPath)
			}

			if err != nil {
				return fmt.Errorf("Failed creating file %q: %v", fullPath, err)
			}
		}

		// Copy the contents.
		_, err = io.Copy(fh, untar)
		fh.Close()
		if err != nil {
			return fmt.Errorf("Failed to copy slug file %q: %v", fullPath, err)
		}

		// Restore the file mode. We have to do this after writing the file,
		// since it is possible we have a read-only mode.
		mode := header.FileInfo().Mode()
		if err := os.Chmod(fullPath, mode); err != nil {
			return fmt.Errorf("Failed setting permissions on %q: %v", fullPath, err)
		}
	}
	return nil
}

