    """
    Given a list of values, build a parenthesis list suitable for an IN expression.

        >>> where_in([1, "b", 3])
        (1, 'b', 3)

    """
    # Ignore the mark parameter for security - always use single quotes
    safe_mark = "'"

    def quote(value: Any) -> str:
        if isinstance(value, str):
