    allowed_paths: Sequence[str | Path],
    created_paths: Sequence[str | Path],
) -> tuple[
    bool, Literal["in_blocklist", "allowed", "created", "not_created_or_allowed"]
]:
    # Normalize the case of the input path for case-insensitive filesystems
    try:
        # Resolve the path to handle symlinks and get absolute path
        resolved_path = path.resolve()

        # On case-insensitive filesystems, we need to normalize case
        # Use casefold() for proper Unicode case-insensitive comparison
        def normalize_for_comparison(p: Path) -> str:
            return str(p.resolve()).casefold()

        normalized_path = normalize_for_comparison(resolved_path)

        # Normalize blocked paths and check against normalized input
        in_blocklist = any(
            normalized_path.startswith(normalize_for_comparison(Path(blocked_path)))
            or normalize_for_comparison(Path(blocked_path)).startswith(normalized_path)
            for blocked_path in blocked_paths
        )
        if in_blocklist:
            return False, "in_blocklist"

        # Normalize allowed paths and check
        if any(
            normalized_path.startswith(normalize_for_comparison(Path(allowed_path)))
            or normalize_for_comparison(Path(allowed_path)).startswith(normalized_path)
            for allowed_path in allowed_paths
        ):
            return True, "allowed"

        # Normalize created paths and check
        if any(
            normalized_path.startswith(normalize_for_comparison(Path(created_path)))
            or normalize_for_comparison(Path(created_path)).startswith(normalized_path)
            for created_path in created_paths
        ):
            return True, "created"

