  var allowedKeys = ['timeout', 'maxBuffer', 'killSignal', 'uid', 'gid', 'cwd', 'env'];
  for (var key in opts) {
    if (opts.hasOwnProperty(key) && allowedKeys.indexOf(key) !== -1) {
      safeOpts[key] = opts[key];
