exports.killByPort = function (port) {
  var processId = null

  // Validate port is a valid integer
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    return
  }

  try {
    var result = execFileSync('lsof', ['-t', `-i:${port}`], { encoding: 'utf8' })
    processId = result.trim()
  } catch (e) {
    // No process found or error occurred
    return
  }

  if (processId) { // if exists kill
    try {
      execFileSync('kill', [processId])
    } catch (e) {
      // Process might have already terminated
    }
  }
}

