function diskusage(path, cb) {
    if (typeof path !== 'string') {
        return process.nextTick(cb, new TypeError('path must be a string'));
    }
    if (path.includes('\0')) {
        return process.nextTick(cb, new Error('path must not contain null bytes'));
    }

    execFile('df', ['-k', path], function(err, stdout) {
        if (err) {
            return cb(err);
        }

        try {
            cb(null, parse(stdout));
        } catch (e) {
            cb(e);
        }
    });
}

