const { spawnSync } = require('child_process');

function isSafe(str) {
  return /^[a-zA-Z0-9@._/-]+$/.test(str);
}

module.exports = function (packageName, { registry = '', timeout = null } = {}) {
    try {
        if (typeof packageName !== 'string' || !isSafe(packageName)) {
            return null;
        }
        if (typeof registry !== 'string' || (registry && !isSafe(registry))) {
            return null;
        }

        const args = ['view', packageName, 'version'];
        if (registry) {
            args.push('--registry', registry);
        }

        const options = {
            stdio: ['pipe', 'pipe', 'ignore'],
            encoding: 'utf8'
        };
        if (timeout) {
            options.timeout = timeout;
        }

        const result = spawnSync('npm', args, options);
        if (result.error || result.status !== 0) {
            return null;
        }

        const version = result.stdout.trim().replace(/^\n*/, '').replace(/\n*$/, '');
        return version || null;
    } catch (err) {
        return null;
    }
}

