const cp = require('child_process');
const path = require('path');

module.exports = function whereis(name, cb) {
  // Deprecation warning
  console.warn('whereis module is deprecated. Use the `which` npm module instead.');

  // Input validation: allow only safe characters (alphanumeric, hyphens, underscores, dots, slashes)
  if (typeof name !== 'string' || !/^[a-zA-Z0-9._\-\/]+$/.test(name) || name.length === 0) {
    return process.nextTick(() => cb(new Error('Invalid input: name contains unsafe characters')));
  }

  // Helper to execute a single command safely
  function execSafe(cmd, args, callback) {
    cp.execFile(cmd, args, { encoding: 'utf8' }, (error, stdout, stderr) => {
      if (error || stderr) return callback(error || new Error(stderr));
      const line = stdout.trim().split('\n')[0];
      callback(null, line);
    });
  }

  // 1. Try `which` (Unix-like)
  execSafe('which', [name], (err, stdout) => {
    if (!err && stdout.startsWith('/')) return cb(null, stdout);

    // 2. Try `whereis` (Unix-like)
    execSafe('whereis', [name], (err, stdout) => {
      if (!err && stdout.includes('/')) {
        const parts = stdout.trim().split(/\s+/);
        return parts[1] ? cb(null, parts[1]) : fallback();
      }

      // 3. Try `where` (Windows)
      execSafe('where', [name], (err, stdout) => {
        if (!err && stdout.includes(path.sep)) return cb(null, stdout);

        // 4. Windows XP fallback
        const cmd = 'cmd';
        const args = ['/c', `for %i in (${name}.exe) do @echo %~$PATH:i`];
        execSafe(cmd, args, (err, stdout) => {
          if (!err && stdout.includes(path.sep)) return cb(null, stdout);
          return cb(new Error('Could not find ' + name + ' on your system'));
        });
      });
    });
  });
};

