func sanitizeIdentifier(s string) string {
	// Allow only alphanumeric, underscore, hyphen, and dot
	return strings.Map(func(r rune) rune {
		if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r == '_' || r == '-' || r == '.' {
			return r
		}
		return -1
	}, s)
