func UntarToDirectory(reader io.Reader, dst string) error {
	visitor := func(entry TarFileEntry) error {
		// Ensure the destination path is clean
		dst = filepath.Clean(dst)
		// Clean the file path from the tar header
		relPath := filepath.Clean(entry.Header.Name)
		// Prevent directory traversal
		if strings.HasPrefix(relPath, "..") || strings.Contains(relPath, "\\") || strings.Contains(relPath, ":") {
			return fmt.Errorf("illegal file path in tar: %s", entry.Header.Name)
		}
		// Join and ensure the final path is within the destination directory
		target := filepath.Join(dst, relPath)
		if !strings.HasPrefix(target, dst) {
			return fmt.Errorf("illegal file path in tar: %s (attempts to escape destination directory)", entry.Header.Name)
		}

		switch entry.Header.Typeflag {
		case tar.TypeDir:
			if _, err := os.Stat(target); err != nil {
				if err := os.MkdirAll(target, 0755); err != nil {
					return err
				}
			}

		case tar.TypeReg:
			f, err := os.OpenFile(target, os.O_CREATE|os.O_RDWR, os.FileMode(entry.Header.Mode))
			if err != nil {
				return err
			}

			// limit the reader on each file read to prevent decompression bomb attacks
			numBytes, err := io.Copy(f, io.LimitReader(entry.Reader, perFileReadLimit))
			if numBytes >= perFileReadLimit || errors.Is(err, io.EOF) {
				return fmt.Errorf("zip read limit hit (potential decompression bomb attack)")
			}
			if err != nil {
				return fmt.Errorf("unable to copy file: %w", err)
			}

			if err = f.Close(); err != nil {
				log.Errorf("failed to close file during untar of path=%q: %w", f.Name(), err)
			}
		}
		return nil
	}

	return IterateTar(reader, visitor)
}

