	} else {
		args = make([]string, len(c.args))
		copy(args, c.args)
		if len(c.args) > 0 {
			args = args[:len(args)-1]
			args = append(args, fsPath)
		}
	}
	c.connection.Log(logger.LevelDebug, "new system command %q, with args: %+v fs path %q quota check path %q",
