func canAcceptRsyncArgs(in []string, user dataprovider.User, destPath string) ([]string, error) {
	allowed := map[string]bool{
		"--archive":        true,
		"--verbose":        true,
		"--compress":       true,
		"--recursive":      true,
		"--times":          true,
		"--perms":          true,
		"--links":          true,
		"--safe-links":     true,
		"--munge-links":    true,
		"--delete":         true,
		"--stats":          true,
		"--human-readable": true,
		"--progress":       true,
		"--dry-run":        true,
		"--exclude":        true,
		"--include":        true,
	}

	out := make([]string, 0, len(in))
	for i := 0; i < len(in); {
		arg := in[i]
		if !strings.HasPrefix(arg, "-") {
			// All remaining arguments must be the final destination path
			break
		}
		if !allowed[arg] {
			return nil, fmt.Errorf("rsync option %q is not allowed", arg)
		}
		out = append(out, arg)
		i++
		// Handle options that take a value
		if arg == "--exclude" || arg == "--include" {
			if i >= len(in) {
				return nil, fmt.Errorf("missing value for option %s", arg)
			}
			val := in[i]
			if strings.Contains(val, "..") || strings.Contains(val, "//") {
				return nil, fmt.Errorf("invalid pattern %q", val)
			}
			out = append(out, val)
			i++
		}
	}

