	if user.HasPerm(dataprovider.PermCreateSymlinks, destPath) {
		if !util.Contains(out, "--safe-links") {
			out = append([]string{"--safe-links"}, out...)
		}
	} else {
		if !util.Contains(out, "--munge-links") {
			out = append([]string{"--munge-links"}, out...)
		}
	}
	return out, nil
}

