res.location = function location(url) {
  var loc = url;

  // "back" is an alias for the referrer
  if (url === 'back') {
    loc = this.req.get('Referrer') || '/';
  } else {
    // Validate the URL to prevent open redirect
    try {
      // Parse with WHATWG URL to ensure well-formed
      var parsed = new URL(loc, 'http://localhost');

      // Reject non-http(s) protocols
      if (!['http:', 'https:'].includes(parsed.protocol)) {
        loc = '/';
      } else if (parsed.hostname !== 'localhost') {
        // Absolute URL: check against allow-list
        var allowedHosts = (this.app && this.app.get('allowedRedirectHosts')) || [];
        if (!allowedHosts.includes(parsed.hostname)) {
          loc = '/';
        }
      }
      // Relative URLs are safe and pass through
    } catch (e) {
      // Malformed URL -> fallback
      loc = '/';
    }
  }

  // set location
  if (!loc) loc = '/';
  return this.set('Location', encodeurl(loc));
};

