_resolvePath(path = '.') {
  const clientPath = (() => {
    path = nodePath.normalize(path);
    if (nodePath.isAbsolute(path)) {
      return nodePath.join(path);
    } else {
      return nodePath.join(this.cwd, path);
    }
  })();

  const fsPath = (() => {
    const resolvedPath = nodePath.join(this.root, clientPath);
    const normalizedPath = nodePath.resolve(nodePath.normalize(nodePath.join(resolvedPath)));

    // Ensure the resolved path is within the root directory
    const relativePath = nodePath.relative(this.root, normalizedPath);
    if (relativePath.startsWith('..') || nodePath.isAbsolute(relativePath)) {
      throw new Error('Path traversal detected');
    }

    return normalizedPath;
  })();

  return {
    clientPath,
    fsPath
  };
}

