		if err != nil {
			return "", fmt.Errorf("getHostByName: DNS lookup failed for %q: %v", host, err)
		}
		if len(addrs) == 0 {
			return "", fmt.Errorf("getHostByName: no addresses found for %q", host)
		}
		return addrs[0], nil
	}

