// isValidDNSLabel validates that the input string is a valid DNS label
// This follows RFC 1123 standards for DNS labels
func isValidDNSLabel(name string) bool {
	if len(name) == 0 || len(name) > 63 {
		return false
	}

	for i, c := range name {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-') {
			return false
		}

		// Cannot start or end with hyphen
		if (i == 0 || i == len(name)-1) && c == '-' {
			return false
		}
	}

	return true
}

