func (r *Registrator) Certificate(ctx context.Context, in *securityapi.CertificateRequest) (resp *securityapi.CertificateResponse, err error) {
	osRoot, err := safe.StateGet[*secrets.OSRoot](ctx, r.Resources, resource.NewMetadata(secrets.NamespaceName, secrets.OSRootType, secrets.OSRootID, resource.VersionUndefined))
	if err != nil {
		return nil, err
	}

	// Get peer information from the gRPC context
	peer, ok := peer.FromContext(ctx)
	if !ok {
		return nil, fmt.Errorf("failed to get peer information")
	}

	// Parse the CSR to extract the requested IP addresses and DNS names
	csrBlock, _ := pem.Decode(in.Csr)
	if csrBlock == nil || csrBlock.Type != "CERTIFICATE REQUEST" {
		return nil, fmt.Errorf("invalid CSR format")
	}

	csr, err := x509.ParseCertificateRequest(csrBlock.Bytes)
	if err != nil {
		return nil, fmt.Errorf("failed to parse CSR: %w", err)
	}

	// Validate that the request is coming from the IP address declared in the CSR
	remoteAddr := peer.Addr.String()
	if remoteAddr == "" {
		return nil, fmt.Errorf("failed to get remote address")
	}

	// Extract IP from remote address (handle both IPv4 and IPv6)
	remoteIP, _, err := net.SplitHostPort(remoteAddr)
	if err != nil {
		// If no port is specified, use the address as-is
		remoteIP = remoteAddr
	}

	// Check if the remote IP matches any IP in the CSR
	ipMatch := false
	for _, ip := range csr.IPAddresses {
		if ip.String() == remoteIP {
			ipMatch = true
			break
		}
	}

	// If no IP match, check DNS names
	dnsMatch := false
	if !ipMatch {
		for _, dns := range csr.DNSNames {
			if resolvedIPs, err := net.LookupIP(dns); err == nil {
				for _, resolvedIP := range resolvedIPs {
					if resolvedIP.String() == remoteIP {
						dnsMatch = true
						break
					}
				}
				if dnsMatch {
					break
				}
			}
		}
	}

	if !ipMatch && !dnsMatch {
		return nil, fmt.Errorf("request source IP %s does not match CSR IP addresses or DNS names", remoteIP)
	}

	// Additional validation: Ensure the request comes from a worker node
	// This could be enhanced with additional checks based on cluster state
	machineConfig, err := safe.StateGet[*config.MachineConfig](ctx, r.Resources, resource.NewMetadata(config.NamespaceName, config.MachineConfigType, config.V1Alpha1ID, resource.VersionUndefined))
	if err != nil {
		return nil, fmt.Errorf("failed to get machine config: %w", err)
	}

	// Verify this is a worker node (not a control plane node)
	if machineConfig.TypedSpec().MachineType == machine.TypeControlPlane {
		return nil, fmt.Errorf("control plane nodes cannot request worker certificates")
	}

	signed, err := x509.NewCertificateFromCSRBytes(osRoot.TypedSpec().CA.Crt, osRoot.TypedSpec().CA.Key, in.Csr)
	if err != nil {
		return
	}

	resp = &securityapi.CertificateResponse{
		Ca:  osRoot.TypedSpec().CA.Crt,
		Crt: signed.X509CertificatePEM,
	}

	return resp, nil
}

