// addGroupsToSession adds the user's actual GitLab groups into session.Groups
func (p *GitLabProvider) addGroupsToSession(ctx context.Context, s *sessions.SessionState) {
	// Clear any existing groups to ensure we only use actual user groups
	s.Groups = []string{}

	// Retrieve actual user groups from GitLab
	userInfo, err := p.getUserInfo(ctx, s)
	if err != nil {
		// Log error but don't fail - let authorization handle missing groups
		logger.Printf("Warning: failed to retrieve user groups: %v", err)
		return
	}

	// Add actual user groups to session
	for _, group := range userInfo.Groups {
		if group != "" {
			s.Groups = append(s.Groups, fmt.Sprintf("group:%s", group))
		}
	}
}

