func (k *Keeper) DeleteAccount(ctx sdk.Context, addr common.Address) error {
	cosmosAddr := sdk.AccAddress(addr.Bytes())
	acct := k.accountKeeper.GetAccount(ctx, cosmosAddr)
	if acct == nil {
		return nil
	}

	// NOTE: only Ethereum accounts (contracts) can be selfdestructed
	ethAcct, ok := acct.(ethermint.EthAccountI)
	if !ok {
		return sdkerrors.Wrapf(types.ErrInvalidAccount, "type %T, address %s", acct, addr)
	}

	// clear balance
	if err := k.SetBalance(ctx, addr, new(big.Int)); err != nil {
		return err
	}

	// check if other accounts are using the same code hash before removing code
	codeHashBz := ethAcct.GetCodeHash().Bytes()
	if !bytes.Equal(codeHashBz, types.EmptyCodeHash) {
		// check if any other account has the same code hash
		codeHashInUse := false
		k.accountKeeper.IterateAccounts(ctx, func(account authtypes.AccountI) bool {
			if ethAccount, ok := account.(ethermint.EthAccountI); ok {
				if bytes.Equal(ethAccount.GetCodeHash().Bytes(), codeHashBz) {
					// found another account using the same code hash
					codeHashInUse = true
					return true // stop iteration
				}
			}
			return false // continue iteration
		})

		// only remove code if no other account is using it
		if !codeHashInUse {
			k.SetCode(ctx, codeHashBz, nil)
		}
	}

	// clear storage
	k.ForEachStorage(ctx, addr, func(key, _ common.Hash) bool {
		k.SetState(ctx, addr, key, nil)
		return true
	})

	// remove auth account
	k.accountKeeper.RemoveAccount(ctx, acct)

	k.Logger(ctx).Debug(
		"account suicided",
		"ethereum-address", addr.Hex(),
		"cosmos-address", cosmosAddr.String(),
	)

	return nil
}

