const path = require('path');

module.exports = (pathInput) => {
  let r = '';
  let remaining = pathInput;

  // Preserve original root string while detecting absolute paths
  while (isAbsolute(remaining)) {
    const isWin = process.platform === 'win32';
    const root = remaining.charAt(0) === '/' ? '/' : (isWin ? path.win32.parse(remaining).root : path.posix.parse(remaining).root);
    remaining = remaining.slice(root.length);
    r += root;
  }

  // Validate remaining path to prevent directory traversal
  const segments = remaining.split(/[/\\]/);
  for (const seg of segments) {
    if (seg === '..' || seg.startsWith('..')) {
      throw new Error('Invalid path: contains directory traversal');
    }
  }

  // Windows drive-local check: C:../foo
  if (process.platform === 'win32' && /^[a-zA-Z]:.*\.\./.test(pathInput)) {
    throw new Error('Invalid path: drive-local directory traversal');
  }

  return [r, remaining];
};

