import (
	"net/url"
	"path"
	"strings"
)

func newRequestFromQuery(settings *backend.DataSourceInstanceSettings, customSettings dataSourceSettings, query dataSourceQuery) (*http.Request, error) {
	baseURL, err := url.Parse(settings.URL)
	if err != nil {
		return nil, err
	}

	// Parse query path as a relative path
	pathURL, err := url.Parse(query.Path)
	if err != nil {
		return nil, fmt.Errorf("invalid path: %v", err)
	}

	// Ensure the path is relative and doesn't contain host or scheme
	if pathURL.IsAbs() {
		return nil, fmt.Errorf("invalid path: absolute URLs not allowed")
	}
	if pathURL.Host != "" {
		return nil, fmt.Errorf("invalid path: hostname not allowed in path")
	}
	if pathURL.Scheme != "" {
		return nil, fmt.Errorf("invalid path: scheme not allowed in path")
	}

	// Clean the path to prevent directory traversal
	cleanPath := path.Clean(pathURL.Path)
	if cleanPath == "." {
		cleanPath = "/"
	}
	if !strings.HasPrefix(cleanPath, "/") {
		cleanPath = "/" + cleanPath
	}

	// Construct the final URL ensuring we maintain the original host and scheme
	finalURL := *baseURL
	finalURL.Path = path.Join(baseURL.Path, cleanPath)
	finalURL.RawQuery = ""
	finalURL.Fragment = ""

	// Double-check that hostname and scheme haven't changed
	if finalURL.Hostname() != baseURL.Hostname() {
		return nil, fmt.Errorf("invalid path: hostname modification not allowed")
	}
	if finalURL.Scheme != baseURL.Scheme {
		return nil, fmt.Errorf("invalid path: scheme modification not allowed")
	}

