func lookupPreprocess(s string) string {
	// Normalize Unicode first to prevent bypass via equivalent characters
	normalized := norm.NFKD.String(s)
	// Then remove dashes, underscores, dots, and spaces
	filtered := regexp.MustCompile(`[-_ .]`).ReplaceAllString(normalized, "")
	return strings.ToLower(filtered)
}

