// isCommandAllowed reports whether the provided command is allowed.
// The check is performed against the first token of the command string.
func isCommandAllowed(cmd string) bool {
	if len(allowedCommands) == 0 {
		return false // default deny
	}
	tokens := strings.Fields(cmd)
	if len(tokens) == 0 {
		return false
	}
	for _, allowed := range allowedCommands {
		if tokens[0] == allowed {
			return true
		}
	}
	return false
}

