func (fs *Filesystem) Delete(p string) error {
	wg := sync.WaitGroup{}

	// Resolve the path but check if it's a symlink first
	resolved := fs.unsafeFilePath(p)
	if !fs.unsafeIsInDataDirectory(resolved) {
		return NewBadPathResolution(p, resolved)
	}

	// Block any whoopsies.
	if resolved == fs.Path() {
		return errors.New("cannot delete root server directory")
	}

	// Check if the path is a symlink
	st, err := os.Lstat(resolved)
	if err != nil {
		if !os.IsNotExist(err) {
			fs.error(err).Warn("error while attempting to stat file before deletion")
		}
		return err
	}

	// Handle symlinks safely - only delete the symlink itself
	if st.Mode()&os.ModeSymlink != 0 {
		// For symlinks, we need to ensure the target is not outside data directory
		target, err := os.Readlink(resolved)
		if err != nil {
			return fmt.Errorf("failed to read symlink target: %w", err)
		}

		// Resolve the target path relative to the symlink's directory
		absTarget := target
		if !filepath.IsAbs(target) {
			absTarget = filepath.Join(filepath.Dir(resolved), target)
		}

		// Check if the symlink target is within data directory
		if !fs.unsafeIsInDataDirectory(absTarget) {
			return NewBadPathResolution(p, absTarget)
		}

		// Only remove the symlink itself, not the target
		return os.Remove(resolved)
	}

	// Handle regular files and directories
	if !st.IsDir() {
		fs.addDisk(-st.Size())
	} else {
		wg.Add(1)
		go func(wg *sync.WaitGroup, st os.FileInfo, resolved string) {
			defer wg.Done()
			if s, err := fs.DirectorySize(resolved); err == nil {
				fs.addDisk(-s)
			}
		}(&wg, st, resolved)
	}

	wg.Wait()

	return os.RemoveAll(resolved)
}

