func (fs *Filesystem) Delete(p string) error {
	wg := sync.WaitGroup{}

	// Resolve the user-provided path relative to the data directory.
	resolved := fs.unsafeFilePath(p)
	if !fs.unsafeIsInDataDirectory(resolved) {
		return NewBadPathResolution(p, resolved)
	}

	// Never allow deleting the root server directory.
	if resolved == fs.Path() {
		return errors.New("cannot delete root server directory")
	}

	// Fully resolve any symlinks in the path.
	// This prevents directory symlinks from escaping the data directory.
	clean, err := filepath.EvalSymlinks(resolved)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		fs.error(err).Warn("error while resolving symlinks before deletion")
		return err
	}
	if !fs.unsafeIsInDataDirectory(clean) {
		return NewBadPathResolution(p, clean)
	}

	// Stat the original path to determine if it's a symlink.
	st, err := os.Lstat(resolved)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		fs.error(err).Warn("error while attempting to stat file before deletion")
		return err
	}

	// If it's a symlink, delete only the link itself.
	if st.Mode()&os.ModeSymlink != 0 {
		return os.Remove(resolved)
	}

	// Handle regular files and directories.
	if !st.IsDir() {
		fs.addDisk(-st.Size())
	} else {
		wg.Add(1)
		go func(wg *sync.WaitGroup, st os.FileInfo, clean string) {
			defer wg.Done()
			if s, err := fs.DirectorySize(clean); err == nil {
				fs.addDisk(-s)
			}
		}(&wg, st, clean)
	}

	wg.Wait()
	return os.RemoveAll(clean)
}

