function buildURL (source, reqBase) {
  const dest = new URL(source, reqBase)

  // if base is specified, source url should not override it
  if (reqBase && !reqBase.startsWith(dest.origin)) {
    throw new Error('source must be a relative path string')
  }

  // Prevent path traversal attacks
  if (reqBase) {
    const basePath = new URL(reqBase).pathname
    const destPath = dest.pathname

    // Normalize paths to prevent directory traversal
    const normalizedBase = basePath.replace(/\/+/g, '/').replace(/\/+$/, '')
    const normalizedDest = destPath.replace(/\/+/g, '/').replace(/\/+$/, '')

    // Ensure the destination path starts with the base path
    if (!normalizedDest.startsWith(normalizedBase)) {
      throw new Error('source path must be within the base path')
    }
  }

  return dest
}

