module.exports = (env) => {
  const toReplace = Object.keys(env).filter((envVar) => {
    // https://github.com/semantic-release/semantic-release/issues/1558
    if (envVar === 'GOPRIVATE') {
      return false;
    }

    return /token|password|credential|secret|private/i.test(envVar) && size(env[envVar].trim()) >= SECRET_MIN_SIZE;
  });

  // Generate both original and URL-encoded versions of secrets
  const allSecrets = [];
  toReplace.forEach((envVar) => {
    const secret = env[envVar].trim();
    allSecrets.push(secret);
    // Add URL-encoded version to catch encoded secrets
    allSecrets.push(encodeURIComponent(secret));
  });

  // Sort by length descending to ensure longest matches are replaced first
  const sortedSecrets = [...new Set(allSecrets)].sort((a, b) => b.length - a.length);

  const regexp = new RegExp(sortedSecrets.map((secret) => escapeRegExp(secret)).join('|'), 'g');
  return (output) =>
    output && isString(output) && sortedSecrets.length > 0 ? output.toString().replace(regexp, SECRET_REPLACEMENT) : output;
};

