def find_profile_dir_by_name(cls, ipython_dir, name=u'default', config=None):
        """Find an existing profile dir by profile name, return its ProfileDir.

        This searches through a sequence of paths for a profile dir.  If it
        is not found, a :class:`ProfileDirError` exception will be raised.

        The search path algorithm is:
        1. ``os.getcwd()``
        2. ``ipython_dir``

        Parameters
        ----------
        ipython_dir : unicode or str
            The IPython directory to use.
        name : unicode or str
            The name of the profile.  The name of the profile directory
            will be "profile_<profile>".
        """
        # Validate profile name to prevent path traversal
        if not name or any(sep in name for sep in ('/', '\\', '..')):
            raise ProfileDirError('Invalid profile name: %s' % name)

        dirname = u'profile_' + name
        paths = [os.getcwd(), ipython_dir]

        # Get current user ID for authorization check
        try:
            current_uid = os.getuid()
        except AttributeError:
            # Windows doesn't have getuid, skip ownership check
            current_uid = None

        for p in paths:
            profile_dir = os.path.join(p, dirname)

            # Ensure path is within authorized boundaries
            try:
                profile_dir = os.path.abspath(profile_dir)
                if not profile_dir.startswith(os.path.abspath(p)):
                    continue
            except (OSError, ValueError):
                continue

            if os.path.isdir(profile_dir):
                # Check ownership/permissions if possible
                if current_uid is not None:
                    try:
                        stat_info = os.stat(profile_dir)
                        if stat_info.st_uid != current_uid and stat_info.st_uid != 0:
                            # Skip directories not owned by current user or root
                            continue
                    except (OSError, AttributeError):
                        # If we can't check ownership, skip for security
                        continue

                return cls(location=profile_dir, config=config)
        else:
            raise ProfileDirError('Profile directory not found in paths: %s' % dirname)

