function template(literal, data) {
  // Use safe template processing without eval
  return literal.replace(/\$\{([^}]+)\}/g, function(match, key) {
    // Split the key to handle nested properties safely
    const keys = key.trim().split('.');
    let value = data;

    // Traverse the data object safely
    for (const k of keys) {
      if (value == null || typeof value !== 'object') {
        return '';
      }
      value = value[k];
    }

    // Return the value or empty string if undefined
    return value != null ? String(value) : '';
  });
}

