async _is_clamav_binary(scanner) {
    const path = this.settings[scanner].path || null;
    if (!path) {
        if (this.settings.debug_mode) console.log(`${this.debug_label}: Could not determine path for clamav binary.`);
        return false;
    }

    // Validate path to prevent command injection
    if (typeof path !== 'string' || path.includes(';') || path.includes('&&') || path.includes('||') || path.includes('`') || path.includes('$(')) {
        if (this.settings.debug_mode) console.log(`${this.debug_label}: Invalid path format for clamav binary.`);
        return false;
    }

    // Ensure path is a valid clamav binary name
    const validBinaries = ['clamdscan', 'clamscan'];
    const binaryName = path.split('/').pop() || path.split('\\').pop();
    if (!validBinaries.includes(binaryName) && !validBinaries.includes(scanner)) {
        if (this.settings.debug_mode) console.log(`${this.debug_label}: Invalid clamav binary name.`);
        return false;
    }

    try {
        await fs_access(path, fs.constants.R_OK);

        // Use spawn instead of exec to avoid shell interpretation
        const { spawn } = require('child_process');
        const child = spawn(path, ['--version'], { stdio: 'pipe' });

        let stdout = '';
        child.stdout.on('data', (data) => {
            stdout += data.toString();
        });

        return new Promise((resolve) => {
            child.on('close', (code) => {
                if (code !== 0) {
                    if (this.settings.debug_mode) console.log(`${this.debug_label}: Could not verify the ${scanner} binary.`);
                    resolve(false);
                    return;
                }

                if (stdout.toString().match(/ClamAV/) === null) {
                    if (this.settings.debug_mode) console.log(`${this.debug_label}: Could not verify the ${scanner} binary.`);
                    resolve(false);
                    return;
                }
                resolve(true);
            });

            child.on('error', () => {
                if (this.settings.debug_mode) console.log(`${this.debug_label}: Could not verify the ${scanner} binary.`);
                resolve(false);
            });
        });
    } catch (err) {
        if (this.settings.debug_mode) console.log(`${this.debug_label}: Could not verify the ${scanner} binary.`);
        return false;
    }
}

