	}
	return false
}

patch:
func PDFHasImage(path string) bool {
	cmd := exec.Command("pdffonts", "-l", "5", path)
	out, err := cmd.Output()
	if err != nil {
		log.Println(err)
		return false
	}
	lines := strings.Split(string(out), "\n")
	if len(lines) < 3 {
		return true
	}
	// Skip header lines (first 2 lines)
	fontLines := lines[2:]
	fontSet := make(map[string]struct{})
	for _, line := range fontLines {
		fields := strings.Fields(line)
		if len(fields) > 0 {
			fontSet[fields[0]] = struct{}{}
		}
	}
	return len(fontSet) == 0
}

