var main = function(req, res) {
        var reqUrl = req.url; 
        //记录请求信息
        logger.http(req, res);

        //使用url解析模块获取url中的路径名 
        var pathName = url.parse(reqUrl).pathname;

        //补全文件路径
        if (path.extname(pathName) == "") {
            if(!/\/$/.test(pathName)){
                pathName += '/';
            }
            pathName += argvs.getDefault();
        }

        //使用路径解析模块,组装实际文件路径 
        var filePath = path.join(argvs.getPath(), pathName);

        // 防止目录遍历：确保解析后的路径在根目录内
        var root = path.resolve(argvs.getPath());
        var resolvedPath = path.resolve(filePath);
        if (!resolvedPath.startsWith(root)) {
            res.writeHead(404, { "Content-Type": "text/html" });
            res.end('<h1>404 Not Found</h1>');
            return;
        }

        //判断文件是否存在 
        fs.exists(resolvedPath, function(exists) {
            try{
                if (exists) {
                    //在返回头中写入内容类型 
                    res.writeHead(200, {
                        "Content-Type": mime.lookup(resolvedPath)
                    });

                    //创建只读流用于返回 
                    var stream = fs.createReadStream(resolvedPath, {
                        flags: "r",
                        encoding: null
                    });

                    //指定如果流读取错误,返回404错误 
                    stream.on("error", function() {
                        res.writeHead(404);
                        res.end('<h1>500 the file [path=' + resolvedPath +'] Read Error!</h1>');
