var execFile = require('child_process').execFile;

module.exports = function(app, cb) {
  // Basic validation: app must be a non-empty string and match Heroku app-name rules
  if (typeof app !== 'string' || !/^[a-z0-9-]+$/.test(app)) {
    return cb(new Error('Invalid app name'));
  }

  execFile('heroku', ['config', '--app', app], function(err, stdout) {
    if (err) return cb(err);
    var config = {};
    var lines = stdout.split('\n');
    lines.shift();
    lines.forEach(function(line) {
      if (!line.trim()) return;
      var parts = line.split(': ');
      if (!parts[1]) {
        console.log('could not parse', line);
      } else {
        config[parts[0].trim()] = parts[1].trim();
      }
    });
    cb(null, config);
  });
}

