trimvideo: (input, start, duration, output) => {
  return new Promise(function(resolve, reject) {
    if (fs.existsSync(input)) {
      // Validate input parameters
      if (typeof start !== 'string' && typeof start !== 'number') {
        reject(new Error("Invalid start parameter"));
        return;
      }
      if (typeof duration !== 'string' && typeof duration !== 'number') {
        reject(new Error("Invalid duration parameter"));
        return;
      }
      if (typeof output !== 'string') {
        reject(new Error("Invalid output parameter"));
        return;
      }

      // Sanitize file paths and parameters
      const sanitizedInput = path.resolve(input);
      const sanitizedOutput = path.resolve(`${output}.mp4`);
      const sanitizedStart = String(start).replace(/[^0-9:.]/g, '');
      const sanitizedDuration = String(duration).replace(/[^0-9:.]/g, '');

      // Use execFile with parameter array to prevent shell injection
      const ffmpegArgs = [
        '-hide_banner',
        '-loglevel', 'quiet',
        '-ss', sanitizedStart,
        '-i', sanitizedInput,
        '-t', sanitizedDuration,
        '-c', 'copy',
        '-y',
        sanitizedOutput
      ];

      execFile('ffmpeg', ffmpegArgs, (error, stdout, stderr) => {
        if (error) {
          reject(error);
          return;
        }
        resolve(sanitizedOutput);
      });
    } else {
      reject(new Error("ffmpegdotjs could not find file"));
    }
  });
},

