    const { execFile } = require('child_process');
    const fs = require('fs');

    return new Promise(function(resolve, reject) {
      if (fs.existsSync(input)) {
        // Validate input parameters
        if (typeof start !== 'string' && typeof start !== 'number') {
          reject(new Error("Invalid start parameter"));
          return;
        }
        if (typeof duration !== 'string' && typeof duration !== 'number') {
          reject(new Error("Invalid duration parameter"));
          return;
        }
        if (typeof output !== 'string') {
          reject(new Error("Invalid output parameter"));
          return;
        }

