          .substring(0, 255); // Limit length

        if (!sanitizedOutputName) {
          reject(new Error("Invalid output filename"));
          return;
        }

        const sanitizedOutput = path.resolve(process.cwd(), `${sanitizedOutputName}.mp4`);

