var path = require('path');

var cleanUrl = function(url, root) {
    // Default root to current working directory if not provided
    root = root || process.cwd();

    // Decode URI components
    var decoded = decodeURIComponent(url);

    // Resolve against the safe root
    var resolved = path.resolve(root, decoded);

    // Ensure the resolved path is still inside the root
    if (!resolved.startsWith(path.resolve(root))) {
        // Path traversal detected – return null to signal rejection
        return null;
    }

    // Return the normalized, safe path relative to root
    return path.relative(root, resolved);
};

