patch:
var path = require('path');

var cleanUrl = function(url, root) {
    // Default root to current working directory if not provided
    root = root || process.cwd();

    // Ensure root is absolute and ends with separator for strict validation
    root = path.resolve(root) + path.sep;

    // Decode URI components and normalize slashes
    var decoded = decodeURIComponent(url);

    // Resolve the path against root and normalize to resolve '..' and '.'
    var resolved = path.resolve(root, decoded);

    // Ensure the resolved path is strictly inside the root
    if (!resolved.startsWith(root)) {
        return null; // Path traversal detected
    }

    // Return the safe relative path (optional, can also return resolved)
    return path.relative(root.slice(0, -1), resolved);
};

