patch:
var path = require('path');

var cleanUrl = function(url, root) {
    if (typeof root !== 'string') {
        throw new TypeError('root directory must be specified');
    }

    // Resolve and normalize the intended root directory
    var safeRoot = path.resolve(root);

    // Resolve and normalize the requested path
    var resolvedPath = path.resolve(safeRoot, url);

    // Ensure the resolved path is still within the root
    if (!resolvedPath.startsWith(safeRoot)) {
        return null; // Directory traversal detected
    }

    // Return the relative path from root (or absolute path)
    return path.relative(safeRoot, resolvedPath);
};

