const dns = require('dns').promises;

const parseUrl = async (url, normalize = false) => {
    // Constants
    const GIT_RE = /(^(git@|http(s)?:\/\/)([\w\.\-@]+)(\/|:))(([\~,\.\w,\-,\_,\/]+)(.git){0,1}((\/){0,1}))/

    if (typeof url !== "string" || !url.trim()) {
        const err = new Error("Invalid url.")
        err.subject_url = url
        throw err
    }

    if (normalize) {
        if (typeof normalize !== "object") {
            normalize = {
                stripHash: false
            }
        }
        url = normalizeUrl(url, normalize)
    }

    const parsed = parsePath(url)

    // SSRF protection: Validate hostname/IP
    if (parsed.hostname) {
        try {
            const addresses = await dns.resolve4(parsed.hostname);
            const isLoopback = addresses.some(addr => {
                // Check for loopback addresses (127.0.0.0/8)
                return addr.startsWith('127.');
            });

            if (isLoopback) {
                const err = new Error("Invalid url.")
                err.subject_url = url
                throw err
            }
        } catch (dnsError) {
            // If DNS resolution fails, treat as invalid
            const err = new Error("Invalid url.")
            err.subject_url = url
            throw err
        }
    }

    // Potential git-ssh urls
    if (parsed.protocol === "file") {
        const matched  = parsed.href.match(GIT_RE)
        if (matched) {
            parsed.protocols = ["ssh"]
            parsed.protocol = "ssh"
            parsed.resource = matched[4]
            parsed.host = matched[4]
            parsed.user = "git"
            parsed.pathname = `/${matched[6]}`
        }
    }

    return parsed;
}

