function cpOptsInData(data, opts) {
  _OPTS.forEach(function (p) {
    if (typeof data[p] != 'undefined') {
      // Disallow setting the root opt for includes via a passed data obj
      // Unsanitized, parameterized use of `render` could allow the
      // include directory to be reset, opening up the possibility of
      // remote code execution
      if (p == 'root') {
        return;
      }

      // Validate input based on expected type for each option
      var value = data[p];
      var isValid = true;

      switch (p) {
        case 'cache':
        case 'debug':
        case 'compileDebug':
        case 'client':
        case 'strict':
        case 'rmWhitespace':
        case 'async':
          isValid = typeof value === 'boolean';
          break;
        case 'filename':
        case 'delimiter':
        case 'openDelimiter':
        case 'closeDelimiter':
          isValid = typeof value === 'string';
          break;
        case 'context':
          isValid = typeof value === 'object' && value !== null;
          break;
        case 'escapeFunction':
          isValid = typeof value === 'function';
          break;
        default:
          // For any other options, ensure basic type safety
          isValid = ['string', 'number', 'boolean', 'object', 'function'].includes(typeof value);
      }

      if (isValid) {
        opts[p] = value;
      }
    }
  });
}

