import ast

def stringToExpression(s, types, context):
    """Given a string, convert it to a tree of ExpressionNode's safely."""
    old_ctx = expressions._context.get_current_context()
    try:
        expressions._context.set_new_context(context)
        flags = __future__.division.compiler_flag if context.get('truediv', False) else 0
        node = compile(s, '<expr>', 'eval', flags)

        # --- Safe evaluation via AST whitelisting ---
        class SafeEvaluator(ast.NodeVisitor):
            def __init__(self):
                self.names = {}
                for name in node.co_names:
                    if name == "None":
                        self.names[name] = None
                    elif name == "True":
                        self.names[name] = True
                    elif name == "False":
                        self.names[name] = False
                    else:
                        t = types.get(name, default_type)
                        self.names[name] = expressions.VariableNode(name, type_to_kind[t])
                self.names.update(expressions.functions)

            def visit(self, node):
                if isinstance(node, ast.Expression):
                    return self.visit(node.body)
                elif isinstance(node, ast.Num):
                    return node.n
                elif isinstance(node, ast.Str):
                    return node.s
                elif isinstance(node, ast.Constant):  # Python 3.8+
                    return node.value
                elif isinstance(node, ast.Name):
                    if node.id not in self.names:
                        raise ValueError(f"Name '{node.id}' is not allowed")
                    return self.names[node.id]
                elif isinstance(node, ast.BinOp):
                    left = self.visit(node.left)
                    right = self.visit(node.right)
                    op = {
                        ast.Add: lambda a, b: a + b,
                        ast.Sub: lambda a, b: a - b,
                        ast.Mult: lambda a, b: a * b,
                        ast.Div: lambda a, b: a / b,
                        ast.Pow: lambda a, b: a ** b,
                        ast.Mod: lambda a, b: a % b,
                        ast.FloorDiv: lambda a, b: a // b,
