                    elif isinstance(node, ast.Constant):  # Python 3.8+
                        return node.value
                    elif isinstance(node, ast.Name):
                        if node.id not in self.names:
                            raise ValueError(f"Name '{node.id}' is not allowed")
                        return self.names[node.id]
